41: export function rowToReserva(row: ReservaDbRow): Reserva {
42:   let horariosArray: string[] = [];
43:   if (Array.isArray(row.horarios)) {
44:     horariosArray = row.horarios;
45:   } else if (typeof row.horarios === "string") {
46:     try {
47:       const parsed = JSON.parse(row.horarios);
48:       if (Array.isArray(parsed)) {
49:         horariosArray = parsed;
50:       }
51:     } catch {
52:       horariosArray = row.horarios.replace(/[{}]/g, "").split(",").map((s) => s.trim()).filter(Boolean);
53:     }
54:   }
55: 
56:   const horaInicio =
57:     row.hora_inicio ??
58:     row.horaInicio ??
59:     (horariosArray.length > 0 ? horariosArray[0] : "08:00");
60: 
61:   const horaFim =
62:     row.hora_fim ??
63:     row.horaFim ??
64:     (horariosArray.length > 0
65:       ? `${String(parseInt(horariosArray[horariosArray.length - 1], 10) + 1).padStart(2, "0")}:00`
66:       : "09:00");
67: 
68:   let userId = row.user_id ?? row.userId ?? undefined;
69:   const rawCpf = String(row.cpf_cliente ?? row.cpfCliente ?? "");
70:   if (!userId && rawCpf.startsWith("uid:")) {
71:     userId = rawCpf.replace("uid:", "");
72:   }
73: 
74:   return {
75:     id: row.id,
76:     userId,
77:     quadraId: row.quadra_id ?? row.quadraId ?? "",
78:     nomeCliente: row.nome_cliente ?? row.nomeCliente ?? "",
79:     whatsappCliente:
