84:     cpfCliente: rawCpf.startsWith("uid:") ? "" : rawCpf,
85:     data: typeof row.data === "string" ? row.data.split("T")[0] : String(row.data),
86:     horarios: horariosArray,
87:     horaInicio,
88:     horaFim,
89:     valorTotal: Number(row.valor_total ?? row.valorTotal ?? 0),
90:     valorSinal: Number(row.valor_sinal ?? row.valorSinal ?? 0),
91:     valorPendente: Number(row.valor_pendente ?? row.valorPendente ?? 0),
