47:       const { user_id, ...rowSemUserId } = row;
48:       const retry = await supabase.from(TABELA_RESERVAS).insert([rowSemUserId]);
49:       error = retry.error;
50:     }
51: 
52:     if (error) {
53:       console.error("[Supabase] Erro ao inserir reserva:", error.message);
54:       return false;
55:     }
56: 
57:     return true;
58:   } catch (err) {
