138: export function subscreverReservasSupabase(
139:   onInsert: (reserva: Reserva) => void,
140:   onUpdate: (reserva: Reserva) => void,
141:   onDelete: (id: string) => void
142: ) {
143:   if (!isSupabaseConfigured()) {
144:     return () => {};
145:   }
146: 
147:   const canal = supabase
148:     .channel("mudancas-reservas-realtime")
149:     .on(
150:       "postgres_changes",
151:       {
152:         event: "INSERT",
153:         schema: "public",
154:         table: TABELA_RESERVAS,
155:       },
156:       (payload) => {
157:         const nova = rowToReserva(payload.new as ReservaDbRow);
158:         onInsert(nova);
159:       }
160:     )
161:     .on(
162:       "postgres_changes",
163:       {
164:         event: "UPDATE",
165:         schema: "public",
166:         table: TABELA_RESERVAS,
167:       },
168:       (payload) => {
169:         const atualizada = rowToReserva(payload.new as ReservaDbRow);
170:         onUpdate(atualizada);
171:       }
172:     )
173:     .on(
174:       "postgres_changes",
175:       {
176:         event: "DELETE",
177:         schema: "public",
178:         table: TABELA_RESERVAS,
179:       },
180:       (payload) => {
181:         const idDeletado = (payload.old as { id?: string })?.id;
182:         if (idDeletado) {
183:           onDelete(idDeletado);
184:         }
185:       }
186:     )
187:     .subscribe();
188: 
189:   return () => {
190:     supabase.removeChannel(canal);
191:   };
192: }
