6:  */
7: 
8: import { create } from "zustand";
9: import { persist } from "zustand/middleware";
10: import type { Esporte } from "@/lib/quadras";
11: 
12: // ─── Tipos ────────────────────────────────────────────────────────────────────
13: 
14: export type StatusReserva =
15:   | "em_processamento" // lock temporário durante o checkout
16:   | "pendente"         // sinal pago, restante a pagar no dia
17:   | "confirmada"       // pagamento do sinal confirmado
18:   | "cancelada";       // reserva cancelada
19: 
20: export type StatusWhatsApp = "nao_enviado" | "enviado" | "falhou";
21: 
22: export interface Reserva {
23:   id: string;
24:   quadraId: string;
25: 
26:   // Identificação do cliente
27:   userId?: string;
28:   nomeCliente: string;
29:   whatsappCliente: string;
30:   cpfCliente: string;
31: 
32:   // Agendamento
33:   data: string;        // "YYYY-MM-DD"
34:   horarios: string[];  // ex: ["13:00", "14:00", "15:00"]
35:   horaInicio: string;  // primeiro slot
36:   horaFim: string;     // última hora + 1h (ex: "16:00")
37: 
38:   // Financeiro
39:   valorTotal: number;
40:   valorSinal: number;    // 40% do total
41:   valorPendente: number; // 60% do total
42: 
43:   // Estado
44:   status: StatusReserva;
45:   statusWhatsApp: StatusWhatsApp;
46:   criadaEm: string; // ISO datetime
47: 
48:   // Opcionais
49:   esporte?: Esporte;
50:   observacoes?: string;
51: }
52: 
53: // ─── State & Actions ──────────────────────────────────────────────────────────
54: 
55: interface ReservasState {
56:   reservas: Reserva[];
57:   isLoadedFromDb: boolean;
58: 
59:   // Mutations
60:   setReservas: (reservas: Reserva[]) => void;
61:   adicionarReserva: (reserva: Reserva) => void;
62:   atualizarReserva: (id: string, dados: Partial<Reserva>) => void;
63:   removerReserva: (id: string) => void;
64: 
65:   // Computed helpers (usados pelo service)
66:   getReservaById: (id: string) => Reserva | undefined;
67:   getReservasPorData: (data: string) => Reserva[];
68: }
69: 
70: // ─── Store ────────────────────────────────────────────────────────────────────
71: 
72: export const useReservasStore = create<ReservasState>()(
73:   persist(
74:     (set, get) => ({
75:       reservas: [],
76:       isLoadedFromDb: false,
77: 
78:       setReservas: (reservas) =>
79:         set({ reservas, isLoadedFromDb: true }),
80: 
81:       adicionarReserva: (reserva) =>
82:         set((state) => {
83:           const existe = state.reservas.some((r) => r.id === reserva.id);
84:           if (existe) {
85:             return {
86:               reservas: state.reservas.map((r) =>
87:                 r.id === reserva.id ? reserva : r
88:               ),
89:             };
90:           }
91:           return { reservas: [reserva, ...state.reservas] };
92:         }),
93: 
94:       atualizarReserva: (id, dados) =>
95:         set((state) => ({
96:           reservas: state.reservas.map((r) =>
97:             r.id === id ? { ...r, ...dados } : r
98:           ),
99:         })),
100: 
101:       removerReserva: (id) =>
102:         set((state) => ({
103:           reservas: state.reservas.filter((r) => r.id !== id),
104:         })),
105: 
106:       getReservaById: (id) => get().reservas.find((r) => r.id === id),
107: 
108:       getReservasPorData: (data) =>
109:         get().reservas.filter((r) => r.data === data),
110:     }),
111:     {
112:       name: "reservei-v2", // versão da chave no LocalStorage (usada como cache/fallback)
113:       partialize: (state) => ({ reservas: state.reservas }),
