/**
 * Tipos de domínio para reservas recorrentes.
 *
 * Um "contrato recorrente" bloqueia horários fixos na agenda por alguns meses.
 * Existem dois tipos, com regras distintas:
 *  - "escolinha": horário divulgado no portal com contato para matrícula.
 *    Não possui regra de cancelamento (contrato robusto, tratado à parte).
 *  - "grupo": grupo comum (mensalista). Horário aparece como "Ocupado" e
 *    possui a regra de cancelamento com aviso de 1 semana.
 */

import type { Esporte } from "@/lib/quadras";

export type TipoContrato = "escolinha" | "grupo";

/** 0 = domingo ... 6 = sábado (mesma convenção de Date#getDay) */
export type DiaSemana = 0 | 1 | 2 | 3 | 4 | 5 | 6;

export const DIAS_SEMANA: ReadonlyArray<{ valor: DiaSemana; curto: string; longo: string }> = [
  { valor: 0, curto: "Dom", longo: "Domingo" },
  { valor: 1, curto: "Seg", longo: "Segunda-feira" },
  { valor: 2, curto: "Ter", longo: "Terça-feira" },
  { valor: 3, curto: "Qua", longo: "Quarta-feira" },
  { valor: 4, curto: "Qui", longo: "Quinta-feira" },
  { valor: 5, curto: "Sex", longo: "Sexta-feira" },
  { valor: 6, curto: "Sáb", longo: "Sábado" },
];

/** Tipo de uma reserva na agenda: avulsa (portal) ou gerada por um contrato */
export type TipoReserva = "avulsa" | TipoContrato;

export interface ContratoRecorrente {
  id: string;
  tipo: TipoContrato;

  /** Nome da escolinha ou do grupo */
  nome: string;
  /** Esporte praticado (obrigatório para escolinhas, opcional para grupos) */
  esporte?: Esporte;
  /** Texto exibido no modal "saiba mais" da escolinha */
  descricao?: string;

  /** Responsável pelo contrato (pessoa de contato interno) */
  responsavelNome: string;
  /** WhatsApp para contato (escolinha: matrícula; grupo: aviso de cancelamento) */
  contatoWhatsapp: string;

  quadraId: string;
  diasSemana: DiaSemana[];
  /** Início do bloco, ex: "14:00" */
  horaInicio: string;
  /** Fim do bloco (exclusivo), ex: "16:00" */
  horaFim: string;

  /** Primeira data de vigência (YYYY-MM-DD) */
  dataInicio: string;
  /** Duração do contrato em meses */
  meses: number;

  ativo: boolean;
  criadoEm: string;
}

/** Dados informados pelo admin no formulário (antes de gerar id/criadoEm) */
export type DadosNovoContrato = Omit<ContratoRecorrente, "id" | "ativo" | "criadoEm">;

/** Duração padrão do bloqueio de agenda (spec: 6 meses) */
export const MESES_PADRAO_CONTRATO = 6;
export const MESES_MAXIMO_CONTRATO = 12;

/**
 * Utilitários de data para recorrência.
 *
 * Todas as datas trafegam como string "YYYY-MM-DD" e são interpretadas no
 * fuso LOCAL. Nunca usamos toISOString() aqui (retorna UTC e desloca o dia).
 */

import type { DiaSemana } from "./types";

const MS_POR_DIA = 24 * 60 * 60 * 1000;

/** Converte "YYYY-MM-DD" em Date local (meia-noite) */
export function parseDataISO(iso: string): Date {
  const [ano, mes, dia] = iso.split("-").map(Number);
  return new Date(ano, mes - 1, dia);
}

/** Converte Date local em "YYYY-MM-DD" */
export function formatarDataISO(data: Date): string {
  const ano = data.getFullYear();
  const mes = String(data.getMonth() + 1).padStart(2, "0");
  const dia = String(data.getDate()).padStart(2, "0");
  return `${ano}-${mes}-${dia}`;
}

/** Valida o formato e a existência real da data (ex.: rejeita 2026-02-30) */
export function isDataISOValida(iso: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(iso)) return false;
  return formatarDataISO(parseDataISO(iso)) === iso;
}

export function adicionarDias(iso: string, dias: number): string {
  const data = parseDataISO(iso);
  data.setDate(data.getDate() + dias);
  return formatarDataISO(data);
}

/**
 * Soma meses preservando o dia quando possível.
 * Se o dia não existir no mês de destino (ex.: 31/08 + 6 meses → fevereiro),
 * usa o último dia do mês de destino.
 */
export function adicionarMeses(iso: string, meses: number): string {
  const [ano, mes, dia] = iso.split("-").map(Number);
  const primeiroDiaDestino = new Date(ano, mes - 1 + meses, 1);
  const ultimoDiaDestino = new Date(
    primeiroDiaDestino.getFullYear(),
    primeiroDiaDestino.getMonth() + 1,
    0
  ).getDate();
  primeiroDiaDestino.setDate(Math.min(dia, ultimoDiaDestino));
  return formatarDataISO(primeiroDiaDestino);
}

export function diaDaSemana(iso: string): DiaSemana {
  return parseDataISO(iso).getDay() as DiaSemana;
}

/**
 * Diferença em dias corridos (ate - de). Usa UTC para não sofrer com
 * mudança de horário de verão.
 */
export function diferencaEmDias(deISO: string, ateISO: string): number {
  const [a1, m1, d1] = deISO.split("-").map(Number);
  const [a2, m2, d2] = ateISO.split("-").map(Number);
  const utcDe = Date.UTC(a1, m1 - 1, d1);
  const utcAte = Date.UTC(a2, m2 - 1, d2);
  return Math.round((utcAte - utcDe) / MS_POR_DIA);
}

/** Formata hora "HH:mm" a partir de um número de hora (ex.: 9 → "09:00") */
export function horaParaTexto(hora: number): string {
  return `${String(hora).padStart(2, "0")}:00`;
}

/** Extrai o número da hora de "HH:mm" */
export function textoParaHora(horario: string): number {
  return parseInt(horario.split(":")[0], 10);
}

