/**
 * Geração, validação e detecção de conflitos de ocorrências recorrentes.
 * Funções puras (sem React, Zustand ou Supabase) para facilitar os testes.
 */

import { HORARIOS_DISPONIVEIS, QUADRAS } from "@/lib/quadras";
import { calcularValorTotal } from "@/lib/constants";
import type { Reserva } from "@/store/useReservasStore";
import {
  adicionarDias,
  adicionarMeses,
  diaDaSemana,
  horaParaTexto,
  isDataISOValida,
  textoParaHora,
} from "./datas";
import {
  MESES_MAXIMO_CONTRATO,
  type ContratoRecorrente,
  type DadosNovoContrato,
  type DiaSemana,
} from "./types";

// ─── Horários ─────────────────────────────────────────────────────────────────

/**
 * Expande um intervalo em slots de 1h.
 * Ex.: ("14:00", "16:00") → ["14:00", "15:00"]
 * Retorna lista vazia se o intervalo for inválido (fim <= início).
 */
export function expandirHorarios(horaInicio: string, horaFim: string): string[] {
  const inicio = textoParaHora(horaInicio);
  const fim = textoParaHora(horaFim);
  if (Number.isNaN(inicio) || Number.isNaN(fim) || fim <= inicio) return [];

  const slots: string[] = [];
  for (let hora = inicio; hora < fim; hora++) {
    slots.push(horaParaTexto(hora));
  }
  return slots;
}

/** Horários de fim aceitos: o fim de cada slot disponível (09:00 ... 23:00) */
export function horariosFimDisponiveis(): string[] {
  return HORARIOS_DISPONIVEIS.map((h) => horaParaTexto(textoParaHora(h) + 1));
}

// ─── Datas ────────────────────────────────────────────────────────────────────

/**
 * Gera todas as datas de um contrato: dias da semana escolhidos entre
 * `dataInicio` (inclusive) e `dataInicio + meses` (exclusive).
 */
export function gerarDatasRecorrentes(
  dataInicio: string,
  diasSemana: DiaSemana[],
  meses: number
): string[] {
  if (!isDataISOValida(dataInicio) || diasSemana.length === 0 || meses <= 0) {
    return [];
  }

  const limite = adicionarMeses(dataInicio, meses);
  const permitidos = new Set<number>(diasSemana);
  const datas: string[] = [];

  for (let atual = dataInicio; atual < limite; atual = adicionarDias(atual, 1)) {
    if (permitidos.has(diaDaSemana(atual))) {
      datas.push(atual);
    }
  }
  return datas;
}

// ─── Validação ────────────────────────────────────────────────────────────────

/** Quantidade mínima de dígitos de um telefone brasileiro com DDD */
const MIN_DIGITOS_TELEFONE = 10;

/**
 * Valida os dados do formulário de contrato.
 * Retorna a lista de mensagens de erro (vazia = dados válidos).
 *
 * @param hoje data de referência "YYYY-MM-DD" (injetável para testes)
 */
export function validarDadosContrato(dados: DadosNovoContrato, hoje: string): string[] {
  const erros: string[] = [];

  if (!dados.nome.trim()) {
    erros.push(dados.tipo === "escolinha" ? "Informe o nome da escolinha." : "Informe o nome do grupo.");
  }

  if (dados.tipo === "escolinha" && !dados.esporte) {
    erros.push("Informe o esporte da escolinha.");
  }

  if (!dados.responsavelNome.trim()) {
    erros.push("Informe o nome do responsável.");
  }

  if (dados.contatoWhatsapp.replace(/\D/g, "").length < MIN_DIGITOS_TELEFONE) {
    erros.push("Informe um WhatsApp válido com DDD.");
  }

  if (!QUADRAS.some((q) => q.id === dados.quadraId)) {
    erros.push("Selecione uma quadra válida.");
  }

  if (dados.diasSemana.length === 0) {
    erros.push("Selecione ao menos um dia da semana.");
  }

  const slots = expandirHorarios(dados.horaInicio, dados.horaFim);
  if (slots.length === 0) {
    erros.push("O horário de fim deve ser posterior ao horário de início.");
  } else if (!slots.every((s) => HORARIOS_DISPONIVEIS.includes(s))) {
    erros.push("O intervalo contém horários fora do funcionamento do complexo.");
  }

  if (!isDataISOValida(dados.dataInicio)) {
    erros.push("Informe uma data de início válida.");
  } else if (dados.dataInicio < hoje) {
    erros.push("A data de início não pode estar no passado.");
  }

  if (!Number.isInteger(dados.meses) || dados.meses < 1 || dados.meses > MESES_MAXIMO_CONTRATO) {
    erros.push(`A duração deve ser de 1 a ${MESES_MAXIMO_CONTRATO} meses.`);
  }

  return erros;
}

// ─── Conflitos ────────────────────────────────────────────────────────────────

export interface ConflitoOcorrencia {
  data: string;
  reservaId: string;
  nomeCliente: string;
  horarios: string[];
}

/** Indica se uma reserva está "segurando" o horário (qualquer status exceto cancelada) */
export function isReservaAtiva(reserva: Reserva): boolean {
  return reserva.status !== "cancelada";
}

/**
 * Procura reservas ativas que colidem com um bloco (quadra + data + horários).
 * `ignorarId` permite checar a própria reserva ao reativá-la.
 */
export function encontrarConflitosDoBloco(
  quadraId: string,
  data: string,
  horarios: string[],
  reservas: Reserva[],
  ignorarId?: string
): Reserva[] {
  return reservas.filter(
    (r) =>
      r.id !== ignorarId &&
      isReservaAtiva(r) &&
      r.quadraId === quadraId &&
      r.data === data &&
      r.horarios.some((h) => horarios.includes(h))
  );
}

/** Detecta conflitos de todas as ocorrências de um contrato com a agenda atual */
export function encontrarConflitosDoContrato(
  dados: Pick<
    DadosNovoContrato,
    "quadraId" | "diasSemana" | "horaInicio" | "horaFim" | "dataInicio" | "meses"
  >,
  reservas: Reserva[]
): ConflitoOcorrencia[] {
  const horarios = expandirHorarios(dados.horaInicio, dados.horaFim);
  const datas = gerarDatasRecorrentes(dados.dataInicio, dados.diasSemana, dados.meses);

  const conflitos: ConflitoOcorrencia[] = [];
  for (const data of datas) {
    for (const reserva of encontrarConflitosDoBloco(dados.quadraId, data, horarios, reservas)) {
      conflitos.push({
        data,
        reservaId: reserva.id,
        nomeCliente: reserva.nomeCliente,
        horarios: reserva.horarios,
      });
    }
  }
  return conflitos;
}

// ─── Materialização ───────────────────────────────────────────────────────────

/** ID determinístico: evita duplicar a mesma ocorrência se a geração rodar duas vezes */
export function gerarIdOcorrencia(contratoId: string, data: string): string {
  return `${contratoId}_${data}`;
}

/**
 * Converte uma data do contrato numa Reserva real da agenda.
 *
 * - Escolinha: sem valores (contrato financeiro tratado à parte), status "confirmada".
 * - Grupo: valor da sessão ao preço normal, nada pago antecipadamente
 *   (sinal 0, pendente = total), status "pendente".
 */
export function montarReservaDaOcorrencia(
  contrato: ContratoRecorrente,
  data: string,
  criadaEm: string = new Date().toISOString()
): Reserva {
  const horarios = expandirHorarios(contrato.horaInicio, contrato.horaFim);
  const ehGrupo = contrato.tipo === "grupo";
  const valorTotal = ehGrupo ? calcularValorTotal(horarios) : 0;

  return {
    id: gerarIdOcorrencia(contrato.id, data),
    quadraId: contrato.quadraId,
    nomeCliente: contrato.nome,
    whatsappCliente: contrato.contatoWhatsapp,
    cpfCliente: "",
    data,
    horarios,
    horaInicio: contrato.horaInicio,
    horaFim: contrato.horaFim,
    valorTotal,
    valorSinal: 0,
    valorPendente: valorTotal,
    status: ehGrupo ? "pendente" : "confirmada",
    statusWhatsApp: "nao_enviado",
    criadaEm,
    esporte: contrato.esporte,
    observacoes:
      contrato.tipo === "escolinha"
        ? `Escolinha: ${contrato.nome}`
        : `Grupo recorrente: ${contrato.nome}`,
    contratoId: contrato.id,
    tipoReserva: contrato.tipo,
  };
}

/** Gera todas as reservas (ocorrências) de um contrato */
export function gerarReservasDoContrato(
  contrato: ContratoRecorrente,
  criadaEm: string = new Date().toISOString()
): Reserva[] {
  return gerarDatasRecorrentes(contrato.dataInicio, contrato.diasSemana, contrato.meses).map(
    (data) => montarReservaDaOcorrencia(contrato, data, criadaEm)
  );
}

/**
 * Regra de cancelamento dos GRUPOS COMUNS (mensalistas).
 *
 * - Aviso com 7 dias ou mais de antecedência → cancela sem ônus.
 * - Aviso tardio (menos de 7 dias) → o horário é liberado ao público, mas:
 *     • se outro cliente reservar e pagar o horário → grupo isento;
 *     • se ninguém ocupar o horário → grupo deve pagar a sessão.
 *
 * Escolinhas NÃO usam estas regras (contratos próprios, fora do escopo).
 */

import type { Reserva } from "@/store/useReservasStore";
import { diferencaEmDias } from "./datas";
import { encontrarConflitosDoBloco } from "./ocorrencias";

/** Antecedência mínima (dias corridos) para cancelar sem ônus */
export const ANTECEDENCIA_MINIMA_DIAS = 7;

export type ClassificacaoAviso = "sem_onus" | "tardio";

export type SituacaoCobranca =
  | "sem_onus" // cancelou com antecedência (ou contrato encerrado)
  | "aguardando_reposicao" // aviso tardio; horário ainda pode ser ocupado por outro cliente
  | "isento_por_reposicao" // aviso tardio, mas outro cliente ocupou e pagou o horário
  | "cobranca_devida"; // aviso tardio; data passou sem reposição

/** Classifica um aviso pela antecedência entre a data do aviso e a da sessão */
export function classificarAviso(dataAviso: string, dataSessao: string): ClassificacaoAviso {
  return diferencaEmDias(dataAviso, dataSessao) >= ANTECEDENCIA_MINIMA_DIAS
    ? "sem_onus"
    : "tardio";
}

export interface ResultadoValidacao {
  ok: boolean;
  motivo?: string;
}

/**
 * Valida o registro de um aviso de cancelamento para uma ocorrência de grupo.
 *
 * @param hoje data de referência "YYYY-MM-DD"
 */
export function validarRegistroCancelamento(
  ocorrencia: Reserva,
  dataAviso: string,
  hoje: string
): ResultadoValidacao {
  if (ocorrencia.tipoReserva !== "grupo") {
    return { ok: false, motivo: "Apenas ocorrências de grupos comuns podem ser canceladas por aviso." };
  }
  if (ocorrencia.status === "cancelada") {
    return { ok: false, motivo: "Esta ocorrência já está cancelada." };
  }
  if (ocorrencia.data < hoje) {
    return { ok: false, motivo: "Não é possível cancelar uma ocorrência que já passou." };
  }
  if (dataAviso > hoje) {
    return { ok: false, motivo: "A data do aviso não pode estar no futuro." };
  }
  if (dataAviso > ocorrencia.data) {
    return { ok: false, motivo: "A data do aviso não pode ser posterior à sessão." };
  }
  return { ok: true };
}

/**
 * Verifica se outro cliente (reserva avulsa já paga ao menos em sinal) ocupou
 * TODOS os horários da ocorrência cancelada.
 */
export function horarioFoiReposto(cancelada: Reserva, todasReservas: Reserva[]): boolean {
  const candidatas = encontrarConflitosDoBloco(
    cancelada.quadraId,
    cancelada.data,
    cancelada.horarios,
    todasReservas,
    cancelada.id
  ).filter(
    (r) =>
      (r.tipoReserva ?? "avulsa") === "avulsa" &&
      (r.status === "pendente" || r.status === "confirmada")
  );

  const cobertos = new Set(candidatas.flatMap((r) => r.horarios));
  return cancelada.horarios.every((h) => cobertos.has(h));
}

/**
 * Situação financeira de uma ocorrência de grupo cancelada.
 *
 * @param hoje data de referência "YYYY-MM-DD"
 */
export function calcularSituacaoCobranca(
  cancelada: Reserva,
  todasReservas: Reserva[],
  hoje: string
): SituacaoCobranca {
  // Sem aviso registrado = cancelamento administrativo (ex.: contrato encerrado)
  if (!cancelada.avisoCancelamentoEm) return "sem_onus";

  if (classificarAviso(cancelada.avisoCancelamentoEm, cancelada.data) === "sem_onus") {
    return "sem_onus";
  }

  if (horarioFoiReposto(cancelada, todasReservas)) return "isento_por_reposicao";

  return cancelada.data < hoje ? "cobranca_devida" : "aguardando_reposicao";
}

export const ROTULO_SITUACAO_COBRANCA: Record<SituacaoCobranca, string> = {
  sem_onus: "Cancelado sem ônus",
  aguardando_reposicao: "Aguardando reposição",
  isento_por_reposicao: "Isento (horário reposto)",
  cobranca_devida: "Cobrança devida",
};

/**
 * Consultas de agenda do portal: quais blocos de escolinha existem
 * para uma quadra/data, para exibir o banner promocional.
 */

import type { Reserva } from "@/store/useReservasStore";
import type { Esporte } from "@/lib/quadras";
import { isReservaAtiva } from "./ocorrencias";
import type { ContratoRecorrente, DiaSemana } from "./types";

export interface AvisoEscolinha {
  contratoId: string;
  nome: string;
  esporte?: Esporte;
  horaInicio: string;
  horaFim: string;
  /** Slots cobertos pelo bloco (ex.: ["14:00", "15:00"]) */
  horarios: string[];
  contatoWhatsapp: string;
  /** Detalhes disponíveis apenas quando o contrato foi carregado */
  descricao?: string;
  responsavelNome?: string;
  diasSemana?: DiaSemana[];
}

/**
 * Lista os blocos de escolinha ativos numa quadra/data, ordenados por horário.
 * Usa os dados da própria reserva e enriquece com o contrato quando disponível,
 * assim o banner funciona mesmo se a tabela de contratos ainda não carregou.
 */
export function obterAvisosEscolinha(
  reservas: Reserva[],
  contratos: ContratoRecorrente[],
  data: string,
  quadraId: string
): AvisoEscolinha[] {
  return reservas
    .filter(
      (r) =>
        r.tipoReserva === "escolinha" &&
        isReservaAtiva(r) &&
        r.data === data &&
        r.quadraId === quadraId
    )
    .map((r) => {
      const contrato = contratos.find((c) => c.id === r.contratoId);
      return {
        contratoId: r.contratoId ?? r.id,
        nome: contrato?.nome ?? r.nomeCliente,
        esporte: contrato?.esporte ?? r.esporte,
        horaInicio: r.horaInicio,
        horaFim: r.horaFim,
        horarios: r.horarios,
        contatoWhatsapp: contrato?.contatoWhatsapp ?? r.whatsappCliente,
        descricao: contrato?.descricao,
        responsavelNome: contrato?.responsavelNome,
        diasSemana: contrato?.diasSemana,
      };
    })
    .sort((a, b) => a.horaInicio.localeCompare(b.horaInicio));
}

/** Slots (de qualquer escolinha) numa quadra/data — úteis para estilizar a grade */
export function obterHorariosEscolinha(avisos: AvisoEscolinha[]): string[] {
  return avisos.flatMap((a) => a.horarios);
}

/** Monta o link do WhatsApp (wa.me) com mensagem pré-preenchida */
export function montarLinkWhatsApp(telefone: string, mensagem: string): string {
  const digitos = telefone.replace(/\D/g, "");
  const numero = digitos.startsWith("55") && digitos.length >= 12 ? digitos : `55${digitos}`;
  return `https://wa.me/${numero}?text=${encodeURIComponent(mensagem)}`;
}

/**
 * Mapeamento entre a tabela `contratos_recorrentes` (snake_case) e a entidade ContratoRecorrente.
 */

import type { Esporte } from "@/lib/quadras";
import type { ContratoRecorrente, DiaSemana, TipoContrato } from "./types";

export interface ContratoDbRow {
  id: string;
  tipo: string;
  nome: string;
  esporte?: string | null;
  descricao?: string | null;
  responsavel_nome: string;
  contato_whatsapp: string;
  quadra_id: string;
  dias_semana: number[] | string;
  hora_inicio: string;
  hora_fim: string;
  data_inicio: string;
  meses: number | string;
  ativo: boolean;
  criado_em?: string;
}

/** Aceita array nativo ou literal do Postgres ("{1,3}") */
function parseDiasSemana(valor: number[] | string): DiaSemana[] {
  const lista = Array.isArray(valor)
    ? valor
    : String(valor)
        .replace(/[{}[\]]/g, "")
        .split(",")
        .map((s) => s.trim())
        .filter(Boolean)
        .map(Number);

  return lista.filter((n) => Number.isInteger(n) && n >= 0 && n <= 6) as DiaSemana[];
}

export function rowToContrato(row: ContratoDbRow): ContratoRecorrente {
  return {
    id: row.id,
    tipo: row.tipo as TipoContrato,
    nome: row.nome,
    esporte: (row.esporte as Esporte) || undefined,
    descricao: row.descricao || undefined,
    responsavelNome: row.responsavel_nome,
    contatoWhatsapp: row.contato_whatsapp,
    quadraId: row.quadra_id,
    diasSemana: parseDiasSemana(row.dias_semana),
    horaInicio: row.hora_inicio,
    horaFim: row.hora_fim,
    dataInicio: typeof row.data_inicio === "string" ? row.data_inicio.split("T")[0] : String(row.data_inicio),
    meses: Number(row.meses),
    ativo: Boolean(row.ativo),
    criadoEm: row.criado_em ?? new Date().toISOString(),
  };
}

export function contratoToRow(contrato: Partial<ContratoRecorrente>): Record<string, unknown> {
  const row: Record<string, unknown> = {};

  if (contrato.id !== undefined) row.id = contrato.id;
  if (contrato.tipo !== undefined) row.tipo = contrato.tipo;
  if (contrato.nome !== undefined) row.nome = contrato.nome;
  if (contrato.esporte !== undefined) row.esporte = contrato.esporte ?? null;
  if (contrato.descricao !== undefined) row.descricao = contrato.descricao ?? null;
  if (contrato.responsavelNome !== undefined) row.responsavel_nome = contrato.responsavelNome;
  if (contrato.contatoWhatsapp !== undefined) row.contato_whatsapp = contrato.contatoWhatsapp;
  if (contrato.quadraId !== undefined) row.quadra_id = contrato.quadraId;
  if (contrato.diasSemana !== undefined) row.dias_semana = contrato.diasSemana;
  if (contrato.horaInicio !== undefined) row.hora_inicio = contrato.horaInicio;
  if (contrato.horaFim !== undefined) row.hora_fim = contrato.horaFim;
  if (contrato.dataInicio !== undefined) row.data_inicio = contrato.dataInicio;
  if (contrato.meses !== undefined) row.meses = contrato.meses;
  if (contrato.ativo !== undefined) row.ativo = contrato.ativo;
  if (contrato.criadoEm !== undefined) row.criado_em = contrato.criadoEm;

  return row;
}

import { supabase, isSupabaseConfigured } from "./client";
import { rowToContrato, contratoToRow, type ContratoDbRow } from "@/lib/recorrencia/contratoMapper";
import type { ContratoRecorrente } from "@/lib/recorrencia/types";

const TABELA_CONTRATOS = "contratos_recorrentes";

/** Busca todos os contratos recorrentes. Retorna null se o Supabase não estiver disponível. */
export async function fetchContratosSupabase(): Promise<ContratoRecorrente[] | null> {
  if (!isSupabaseConfigured()) return null;

  try {
    const { data, error } = await supabase
      .from(TABELA_CONTRATOS)
      .select("*")
      .order("criado_em", { ascending: false });

    if (error) {
      console.error("[Supabase] Erro ao carregar contratos:", error.message);
      return null;
    }
    return (data as ContratoDbRow[]).map(rowToContrato);
  } catch (err) {
    console.error("[Supabase] Falha inesperada ao buscar contratos:", err);
    return null;
  }
}

/** Insere um contrato. Retorna true em caso de sucesso. */
export async function inserirContratoSupabase(contrato: ContratoRecorrente): Promise<boolean> {
  if (!isSupabaseConfigured()) return false;

  try {
    const { error } = await supabase.from(TABELA_CONTRATOS).insert([contratoToRow(contrato)]);
    if (error) {
      console.error("[Supabase] Erro ao inserir contrato:", error.message);
      return false;
    }
    return true;
  } catch (err) {
    console.error("[Supabase] Falha inesperada ao inserir contrato:", err);
    return false;
  }
}

/** Atualiza campos de um contrato existente. */
export async function atualizarContratoSupabase(
  id: string,
  dados: Partial<ContratoRecorrente>
): Promise<boolean> {
  if (!isSupabaseConfigured()) return false;

  try {
    const { error } = await supabase
      .from(TABELA_CONTRATOS)
      .update(contratoToRow(dados))
      .eq("id", id);

    if (error) {
      console.error(`[Supabase] Erro ao atualizar contrato ${id}:`, error.message);
      return false;
    }
    return true;
  } catch (err) {
    console.error(`[Supabase] Falha inesperada ao atualizar contrato ${id}:`, err);
    return false;
  }
}

/**
 * Store global dos contratos recorrentes (escolinhas e grupos).
 * Cache em LocalStorage; fonte de verdade é o Supabase.
 * Componentes de UI devem usar o hook @/hooks/useContratosService.
 */

import { create } from "zustand";
import { persist } from "zustand/middleware";
import type { ContratoRecorrente } from "@/lib/recorrencia/types";

interface ContratosState {
  contratos: ContratoRecorrente[];
  isLoadedFromDb: boolean;

  setContratos: (contratos: ContratoRecorrente[]) => void;
  adicionarContrato: (contrato: ContratoRecorrente) => void;
  atualizarContrato: (id: string, dados: Partial<ContratoRecorrente>) => void;
  getContratoById: (id: string) => ContratoRecorrente | undefined;
}

export const useContratosStore = create<ContratosState>()(
  persist(
    (set, get) => ({
      contratos: [],
      isLoadedFromDb: false,

      setContratos: (contratos) => set({ contratos, isLoadedFromDb: true }),

      adicionarContrato: (contrato) =>
        set((state) => {
          const existe = state.contratos.some((c) => c.id === contrato.id);
          if (existe) {
            return {
              contratos: state.contratos.map((c) => (c.id === contrato.id ? contrato : c)),
            };
          }
          return { contratos: [contrato, ...state.contratos] };
        }),

      atualizarContrato: (id, dados) =>
        set((state) => ({
          contratos: state.contratos.map((c) => (c.id === id ? { ...c, ...dados } : c)),
        })),

      getContratoById: (id) => get().contratos.find((c) => c.id === id),
    }),
    {
      name: "reservei-contratos-v1",
      partialize: (state) => ({ contratos: state.contratos }),
    }
  )
);

