/**
 * Camada de abstração para contratos recorrentes (escolinhas e grupos comuns).
 * Orquestra: validação → geração das ocorrências → persistência (Supabase) → estado local.
 * Componentes de UI não devem acessar stores ou Supabase diretamente.
 */

"use client";

import { useCallback, useEffect, useMemo } from "react";
import { useContratosStore } from "@/store/useContratosStore";
import { useReservasStore, type Reserva } from "@/store/useReservasStore";
import { useReservasService } from "@/hooks/useReservasService";
import { getHoje } from "@/lib/constants";
import { isSupabaseConfigured } from "@/lib/supabase/client";
import {
  fetchContratosSupabase,
  inserirContratoSupabase,
  atualizarContratoSupabase,
} from "@/lib/supabase/contratosService";
import {
  atualizarReservaSupabase,
  atualizarReservasEmLoteSupabase,
  inserirReservasEmLoteSupabase,
} from "@/lib/supabase/reservasService";
import {
  encontrarConflitosDoBloco,
  encontrarConflitosDoContrato,
  gerarReservasDoContrato,
  validarDadosContrato,
  type ConflitoOcorrencia,
} from "@/lib/recorrencia/ocorrencias";
import {
  calcularSituacaoCobranca,
  classificarAviso,
  validarRegistroCancelamento,
  type ClassificacaoAviso,
  type SituacaoCobranca,
} from "@/lib/recorrencia/cancelamento";
import { obterAvisosEscolinha, type AvisoEscolinha } from "@/lib/recorrencia/agenda";
import type {
  ContratoRecorrente,
  DadosNovoContrato,
  TipoContrato,
} from "@/lib/recorrencia/types";

// ─── Tipos de resultado ───────────────────────────────────────────────────────

export type ResultadoCriarContrato =
  | { ok: true; contrato: ContratoRecorrente; totalOcorrencias: number }
  | { ok: false; erros: string[]; conflitos?: ConflitoOcorrencia[] };

export type ResultadoCancelamento =
  | { ok: true; classificacao: ClassificacaoAviso }
  | { ok: false; motivo: string };

export type ResultadoSimples = { ok: true } | { ok: false; motivo: string };

function gerarIdContrato(): string {
  return `ctr_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
}

// ─── Hook ─────────────────────────────────────────────────────────────────────

export function useContratosService() {
  // Garante que as reservas (incluindo ocorrências materializadas) estejam sincronizadas
  const { reservas } = useReservasService();

  const contratos = useContratosStore((s) => s.contratos);
  const setContratos = useContratosStore((s) => s.setContratos);
  const isLoadedFromDb = useContratosStore((s) => s.isLoadedFromDb);

  // ── Sincronização inicial ──────────────────────────────────────────────────
  useEffect(() => {
    let isMounted = true;
    if (!isSupabaseConfigured()) return;

    fetchContratosSupabase().then((dados) => {
      if (isMounted && dados) setContratos(dados);
    });

    return () => {
      isMounted = false;
    };
  }, [setContratos]);

  // ── Queries ────────────────────────────────────────────────────────────────

  const getContratosPorTipo = useCallback(
    (tipo: TipoContrato): ContratoRecorrente[] => contratos.filter((c) => c.tipo === tipo),
    [contratos]
  );

  /** Ocorrências (reservas) de um contrato, em ordem cronológica */
  const getOcorrencias = useCallback(
    (contratoId: string): Reserva[] =>
      reservas
        .filter((r) => r.contratoId === contratoId)
        .sort((a, b) => a.data.localeCompare(b.data)),
    [reservas]
  );

  const getAvisosEscolinha = useCallback(
    (data: string, quadraId: string): AvisoEscolinha[] =>
      obterAvisosEscolinha(reservas, contratos, data, quadraId),
    [reservas, contratos]
  );

  const getSituacaoCobranca = useCallback(
    (cancelada: Reserva): SituacaoCobranca =>
      calcularSituacaoCobranca(cancelada, reservas, getHoje()),
    [reservas]
  );

  // ── Mutations ──────────────────────────────────────────────────────────────

  /**
   * Cria um contrato e materializa todas as ocorrências na agenda.
   * Bloqueia a criação se alguma data colidir com reservas existentes.
   * Com Supabase configurado, só altera o estado local se o banco confirmar.
   */
  const criarContrato = useCallback(
    async (dados: DadosNovoContrato): Promise<ResultadoCriarContrato> => {
      const erros = validarDadosContrato(dados, getHoje());
      if (erros.length > 0) return { ok: false, erros };

      const reservasAtuais = useReservasStore.getState().reservas;
      const conflitos = encontrarConflitosDoContrato(dados, reservasAtuais);
      if (conflitos.length > 0) {
        return {
          ok: false,
          erros: [
            `${conflitos.length} data(s) do contrato colidem com reservas existentes. Cancele-as ou ajuste o período.`,
          ],
          conflitos,
        };
      }

      const contrato: ContratoRecorrente = {
        ...dados,
        nome: dados.nome.trim(),
        responsavelNome: dados.responsavelNome.trim(),
        descricao: dados.descricao?.trim() || undefined,
        id: gerarIdContrato(),
        ativo: true,
        criadoEm: new Date().toISOString(),
      };

      const ocorrencias = gerarReservasDoContrato(contrato);
      if (ocorrencias.length === 0) {
        return { ok: false, erros: ["Nenhuma data foi gerada para o período informado."] };
      }

      if (isSupabaseConfigured()) {
        const contratoSalvo = await inserirContratoSupabase(contrato);
        if (!contratoSalvo) {
          return {
            ok: false,
            erros: [
              "Não foi possível salvar o contrato no banco. Verifique se a migração do schema.sql foi aplicada.",
            ],
          };
        }

        const reservasSalvas = await inserirReservasEmLoteSupabase(ocorrencias);
        if (!reservasSalvas) {
          await atualizarContratoSupabase(contrato.id, { ativo: false });
          return {
            ok: false,
            erros: ["Não foi possível bloquear os horários na agenda. O contrato foi desativado."],
          };
        }
      }

      useContratosStore.getState().adicionarContrato(contrato);
      useReservasStore.setState((state) => {
        const idsNovos = new Set(ocorrencias.map((o) => o.id));
        return {
          reservas: [...ocorrencias, ...state.reservas.filter((r) => !idsNovos.has(r.id))],
        };
      });

      return { ok: true, contrato, totalOcorrencias: ocorrencias.length };
    },
    []
  );

  /**
   * Grupo comum: registra o aviso de cancelamento de uma sessão.
   * Libera o horário ao público e classifica o aviso (sem ônus × tardio).
   */
  const registrarCancelamentoGrupo = useCallback(
    (reservaId: string, dataAviso: string = getHoje()): ResultadoCancelamento => {
      const ocorrencia = useReservasStore.getState().getReservaById(reservaId);
      if (!ocorrencia) return { ok: false, motivo: "Ocorrência não encontrada." };

      const validacao = validarRegistroCancelamento(ocorrencia, dataAviso, getHoje());
      if (!validacao.ok) return { ok: false, motivo: validacao.motivo ?? "Cancelamento inválido." };

      const atualizacao: Partial<Reserva> = {
        status: "cancelada",
        avisoCancelamentoEm: dataAviso,
      };
      useReservasStore.getState().atualizarReserva(reservaId, atualizacao);
      void atualizarReservaSupabase(reservaId, atualizacao);

      return { ok: true, classificacao: classificarAviso(dataAviso, ocorrencia.data) };
    },
    []
  );

  /**
   * Desfaz o cancelamento de uma sessão de grupo, desde que o horário
   * ainda esteja livre (ninguém reservou nesse meio-tempo).
   */
  const reativarOcorrenciaGrupo = useCallback((reservaId: string): ResultadoSimples => {
    const { reservas: atuais, getReservaById } = useReservasStore.getState();
    const ocorrencia = getReservaById(reservaId);

    if (!ocorrencia || ocorrencia.tipoReserva !== "grupo") {
      return { ok: false, motivo: "Ocorrência de grupo não encontrada." };
    }
    if (ocorrencia.status !== "cancelada") {
      return { ok: false, motivo: "Esta ocorrência não está cancelada." };
    }
    if (ocorrencia.data < getHoje()) {
      return { ok: false, motivo: "Não é possível reativar uma sessão que já passou." };
    }
    const conflitos = encontrarConflitosDoBloco(
      ocorrencia.quadraId,
      ocorrencia.data,
      ocorrencia.horarios,
      atuais,
      ocorrencia.id
    );
    if (conflitos.length > 0) {
      return { ok: false, motivo: "O horário já foi reservado por outro cliente." };
    }

    const atualizacao: Partial<Reserva> = { status: "pendente", avisoCancelamentoEm: null };
    useReservasStore.getState().atualizarReserva(reservaId, atualizacao);
    void atualizarReservaSupabase(reservaId, atualizacao);
    return { ok: true };
  }, []);

  /**
   * Encerra um contrato: desativa e cancela (sem ônus) as sessões de hoje em diante.
   * Sessões passadas permanecem no histórico.
   */
  const encerrarContrato = useCallback(
    async (contratoId: string): Promise<{ ok: boolean; sessoesCanceladas: number }> => {
      const hoje = getHoje();
      const futuras = useReservasStore
        .getState()
        .reservas.filter(
          (r) => r.contratoId === contratoId && r.data >= hoje && r.status !== "cancelada"
        );
      const ids = futuras.map((r) => r.id);

      if (isSupabaseConfigured()) {
        const contratoAtualizado = await atualizarContratoSupabase(contratoId, { ativo: false });
        if (!contratoAtualizado) return { ok: false, sessoesCanceladas: 0 };
        if (ids.length > 0) {
          const reservasAtualizadas = await atualizarReservasEmLoteSupabase(ids, {
            status: "cancelada",
          });
          if (!reservasAtualizadas) return { ok: false, sessoesCanceladas: 0 };
        }
      }

      useContratosStore.getState().atualizarContrato(contratoId, { ativo: false });
      const idsSet = new Set(ids);
      useReservasStore.setState((state) => ({
        reservas: state.reservas.map((r) =>
          idsSet.has(r.id) ? { ...r, status: "cancelada" as const } : r
        ),
      }));

      return { ok: true, sessoesCanceladas: ids.length };
    },
    []
  );

  return useMemo(
    () => ({
      contratos,
      isLoadedFromDb,
      // Queries
      getContratosPorTipo,
      getOcorrencias,
      getAvisosEscolinha,
      getSituacaoCobranca,
      // Mutations
      criarContrato,
      registrarCancelamentoGrupo,
      reativarOcorrenciaGrupo,
      encerrarContrato,
    }),
    [
      contratos,
      isLoadedFromDb,
      getContratosPorTipo,
      getOcorrencias,
      getAvisosEscolinha,
      getSituacaoCobranca,
      criarContrato,
      registrarCancelamentoGrupo,
      reativarOcorrenciaGrupo,
      encerrarContrato,
    ]
  );
}

/**
 * Formulário de cadastro de contrato recorrente.
 * Reutilizado pelas telas de Escolinhas e de Grupos (muda apenas o `tipo`).
 */

"use client";

import { useMemo, useState } from "react";
import { Loader2 } from "lucide-react";
import { ESPORTES, HORARIOS_DISPONIVEIS, QUADRAS, type Esporte } from "@/lib/quadras";
import { getHoje, mascaraWhatsApp } from "@/lib/constants";
import { horariosFimDisponiveis, expandirHorarios, gerarDatasRecorrentes } from "@/lib/recorrencia/ocorrencias";
import { formatarDataExibicao } from "@/lib/constants";
import {
  DIAS_SEMANA,
  MESES_MAXIMO_CONTRATO,
  MESES_PADRAO_CONTRATO,
  type DadosNovoContrato,
  type DiaSemana,
  type TipoContrato,
} from "@/lib/recorrencia/types";
import type { ResultadoCriarContrato } from "@/hooks/useContratosService";

interface Props {
  tipo: TipoContrato;
  onSubmit: (dados: DadosNovoContrato) => Promise<ResultadoCriarContrato>;
  onSucesso: (resultado: Extract<ResultadoCriarContrato, { ok: true }>) => void;
  onCancelar: () => void;
}

const CLASSE_INPUT =
  "w-full bg-slate-800 border border-slate-700 rounded-xl px-3 py-2.5 text-sm text-white placeholder:text-slate-500 focus:outline-none focus:border-emerald-500/60 transition-colors";
const CLASSE_LABEL = "block text-xs font-semibold text-slate-400 mb-1.5";

const TEXTOS: Record<TipoContrato, { nome: string; placeholderNome: string; titulo: string }> = {
  escolinha: {
    nome: "Nome da escolinha",
    placeholderNome: "Ex.: Escolinha Craques do Futuro",
    titulo: "Nova escolinha",
  },
  grupo: {
    nome: "Nome do grupo",
    placeholderNome: "Ex.: Pelada dos Amigos de Terça",
    titulo: "Novo grupo",
  },
};

export function FormularioContrato({ tipo, onSubmit, onSucesso, onCancelar }: Props) {
  const textos = TEXTOS[tipo];
  const hoje = getHoje();

  const [nome, setNome] = useState("");
  const [esporte, setEsporte] = useState<Esporte | "">("");
  const [descricao, setDescricao] = useState("");
  const [responsavelNome, setResponsavelNome] = useState("");
  const [contatoWhatsapp, setContatoWhatsapp] = useState("");
  const [quadraId, setQuadraId] = useState(QUADRAS[0].id);
  const [diasSemana, setDiasSemana] = useState<DiaSemana[]>([]);
  const [horaInicio, setHoraInicio] = useState("14:00");
  const [horaFim, setHoraFim] = useState("16:00");
  const [dataInicio, setDataInicio] = useState(hoje);
  const [meses, setMeses] = useState(MESES_PADRAO_CONTRATO);

  const [enviando, setEnviando] = useState(false);
  const [erros, setErros] = useState<string[]>([]);
  const [conflitos, setConflitos] = useState<Array<{ data: string; nomeCliente: string }>>([]);

  const totalSessoes = useMemo(
    () => gerarDatasRecorrentes(dataInicio, diasSemana, meses).length,
    [dataInicio, diasSemana, meses]
  );
  const horasPorSessao = expandirHorarios(horaInicio, horaFim).length;

  function alternarDia(dia: DiaSemana) {
    setDiasSemana((atual) =>
      atual.includes(dia) ? atual.filter((d) => d !== dia) : [...atual, dia].sort()
    );
  }

  async function handleSubmit(evento: React.FormEvent) {
    evento.preventDefault();
    setErros([]);
    setConflitos([]);
    setEnviando(true);

    try {
      const resultado = await onSubmit({
        tipo,
        nome,
        esporte: esporte || undefined,
        descricao: tipo === "escolinha" ? descricao : undefined,
        responsavelNome,
        contatoWhatsapp,
        quadraId,
        diasSemana,
        horaInicio,
        horaFim,
        dataInicio,
        meses,
      });

      if (resultado.ok) {
        onSucesso(resultado);
      } else {
        setErros(resultado.erros);
        setConflitos(resultado.conflitos ?? []);
      }
    } finally {
      setEnviando(false);
    }
  }

  return (
    <form
      onSubmit={handleSubmit}
      id={`form-contrato-${tipo}`}
      className="bg-slate-900 border border-slate-700/50 rounded-2xl p-5 sm:p-6 space-y-5"
    >
      <h2 className="text-lg font-bold text-white">{textos.titulo}</h2>

      <div className="grid sm:grid-cols-2 gap-4">
        <div className="sm:col-span-2">
          <label htmlFor={`${tipo}-nome`} className={CLASSE_LABEL}>
            {textos.nome}
          </label>
          <input
            id={`${tipo}-nome`}
            className={CLASSE_INPUT}
            value={nome}
            onChange={(e) => setNome(e.target.value)}
            placeholder={textos.placeholderNome}
          />
        </div>

        <div>
          <label htmlFor={`${tipo}-esporte`} className={CLASSE_LABEL}>
            Esporte {tipo === "grupo" && <span className="text-slate-600">(opcional)</span>}
          </label>
          <select
            id={`${tipo}-esporte`}
            className={CLASSE_INPUT}
            value={esporte}
            onChange={(e) => setEsporte(e.target.value as Esporte | "")}
          >
            <option value="">Selecione...</option>
            {ESPORTES.map((e) => (
              <option key={e} value={e}>
                {e}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label htmlFor={`${tipo}-quadra`} className={CLASSE_LABEL}>
            Quadra
          </label>
          <select
            id={`${tipo}-quadra`}
            className={CLASSE_INPUT}
            value={quadraId}
            onChange={(e) => setQuadraId(e.target.value)}
          >
            {QUADRAS.map((q) => (
              <option key={q.id} value={q.id}>
                Quadra {q.numero}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label htmlFor={`${tipo}-responsavel`} className={CLASSE_LABEL}>
            Responsável
          </label>
          <input
            id={`${tipo}-responsavel`}
            className={CLASSE_INPUT}
            value={responsavelNome}
            onChange={(e) => setResponsavelNome(e.target.value)}
            placeholder="Nome do responsável"
          />
        </div>

        <div>
          <label htmlFor={`${tipo}-whatsapp`} className={CLASSE_LABEL}>
            {tipo === "escolinha" ? "WhatsApp para matrículas" : "WhatsApp do responsável"}
          </label>
          <input
            id={`${tipo}-whatsapp`}
            className={CLASSE_INPUT}
            value={contatoWhatsapp}
            onChange={(e) => setContatoWhatsapp(mascaraWhatsApp(e.target.value))}
            placeholder="(00) 00000-0000"
            inputMode="tel"
          />
        </div>

        {tipo === "escolinha" && (
          <div className="sm:col-span-2">
            <label htmlFor="escolinha-descricao" className={CLASSE_LABEL}>
              Descrição <span className="text-slate-600">(exibida no &quot;saiba mais&quot; do portal)</span>
            </label>
            <textarea
              id="escolinha-descricao"
              className={`${CLASSE_INPUT} min-h-[80px] resize-y`}
              value={descricao}
              onChange={(e) => setDescricao(e.target.value)}
              placeholder="Faixa etária, metodologia, valores da mensalidade, etc."
            />
          </div>
        )}
      </div>

      {/* Dias da semana */}
      <div>
        <p className={CLASSE_LABEL}>Dias da semana</p>
        <div className="flex flex-wrap gap-2">
          {DIAS_SEMANA.map((dia) => {
            const ativo = diasSemana.includes(dia.valor);
            return (
              <button
                key={dia.valor}
                type="button"
                id={`${tipo}-dia-${dia.valor}`}
                aria-pressed={ativo}
                onClick={() => alternarDia(dia.valor)}
                className={`px-3.5 py-2 rounded-xl text-xs font-semibold border transition-colors ${
                  ativo
                    ? "bg-emerald-500/20 border-emerald-500 text-emerald-300"
                    : "bg-slate-800 border-slate-700 text-slate-400 hover:text-white"
                }`}
              >
                {dia.curto}
              </button>
            );
          })}
        </div>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        <div>
          <label htmlFor={`${tipo}-inicio`} className={CLASSE_LABEL}>
            Início
          </label>
          <select
            id={`${tipo}-inicio`}
            className={CLASSE_INPUT}
            value={horaInicio}
            onChange={(e) => setHoraInicio(e.target.value)}
          >
            {HORARIOS_DISPONIVEIS.map((h) => (
              <option key={h} value={h}>
                {h}
              </option>
            ))}
          </select>
        </div>
        <div>
          <label htmlFor={`${tipo}-fim`} className={CLASSE_LABEL}>
            Fim
          </label>
          <select
            id={`${tipo}-fim`}
            className={CLASSE_INPUT}
            value={horaFim}
            onChange={(e) => setHoraFim(e.target.value)}
          >
            {horariosFimDisponiveis().map((h) => (
              <option key={h} value={h}>
                {h}
              </option>
            ))}
          </select>
        </div>
        <div>
          <label htmlFor={`${tipo}-data-inicio`} className={CLASSE_LABEL}>
            A partir de
          </label>
          <input
            id={`${tipo}-data-inicio`}
            type="date"
            className={CLASSE_INPUT}
            min={hoje}
            value={dataInicio}
            onChange={(e) => setDataInicio(e.target.value)}
          />
        </div>
        <div>
          <label htmlFor={`${tipo}-meses`} className={CLASSE_LABEL}>
            Duração
          </label>
          <select
            id={`${tipo}-meses`}
            className={CLASSE_INPUT}
            value={meses}
            onChange={(e) => setMeses(Number(e.target.value))}
          >
            {Array.from({ length: MESES_MAXIMO_CONTRATO }, (_, i) => i + 1).map((m) => (
              <option key={m} value={m}>
                {m} {m === 1 ? "mês" : "meses"}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Prévia */}
      <p className="text-xs text-slate-400 bg-slate-800/60 border border-slate-700/50 rounded-xl px-3.5 py-2.5">
        {totalSessoes > 0 && horasPorSessao > 0 ? (
          <>
            Serão bloqueadas <strong className="text-white">{totalSessoes} sessões</strong> de{" "}
            {horasPorSessao}h, até{" "}
            {formatarDataExibicao(
              gerarDatasRecorrentes(dataInicio, diasSemana, meses).slice(-1)[0],
              { day: "numeric", month: "long", year: "numeric" }
            )}
            .
          </>
        ) : (
          "Preencha os dias, horários e data de início para ver quantas sessões serão bloqueadas."
        )}
      </p>

      {/* Erros */}
      {erros.length > 0 && (
        <div
          role="alert"
          className="bg-red-500/10 border border-red-500/30 rounded-xl px-4 py-3 text-sm text-red-300 space-y-1"
        >
          {erros.map((erro) => (
            <p key={erro}>• {erro}</p>
          ))}
          {conflitos.length > 0 && (
            <ul className="mt-2 text-xs text-red-300/80 list-disc pl-5 space-y-0.5">
              {conflitos.slice(0, 8).map((c) => (
                <li key={`${c.data}-${c.nomeCliente}`}>
                  {formatarDataExibicao(c.data)} — {c.nomeCliente || "Reserva sem nome"}
                </li>
              ))}
              {conflitos.length > 8 && <li>… e mais {conflitos.length - 8}.</li>}
            </ul>
          )}
        </div>
      )}

      <div className="flex flex-col-reverse sm:flex-row sm:justify-end gap-3 pt-1">
        <button
          type="button"
          onClick={onCancelar}
          className="px-5 py-2.5 rounded-xl text-sm font-medium text-slate-300 bg-slate-800 border border-slate-700 hover:text-white transition-colors"
        >
          Cancelar
        </button>
        <button
          type="submit"
          id={`${tipo}-salvar`}
          disabled={enviando}
          className="px-5 py-2.5 rounded-xl text-sm font-bold text-slate-950 bg-emerald-500 hover:bg-emerald-400 disabled:opacity-60 transition-colors flex items-center justify-center gap-2"
        >
          {enviando && <Loader2 className="w-4 h-4 animate-spin" />}
          Cadastrar e bloquear agenda
        </button>
      </div>
    </form>
  );
}

/**
 * Cartão-resumo de um contrato recorrente (escolinha ou grupo).
 * O conteúdo específico de cada tela (ações, sessões) entra via `children`.
 */

import { CalendarDays, Clock, MapPin, Phone, User } from "lucide-react";
import { mascaraWhatsApp, formatarDataExibicao } from "@/lib/constants";
import { QUADRAS } from "@/lib/quadras";
import { DIAS_SEMANA, type ContratoRecorrente } from "@/lib/recorrencia/types";

interface Props {
  contrato: ContratoRecorrente;
  /** Quantas sessões ainda ativas (hoje em diante) */
  sessoesFuturas: number;
  children?: React.ReactNode;
}

export function CartaoContrato({ contrato, sessoesFuturas, children }: Props) {
  const quadra = QUADRAS.find((q) => q.id === contrato.quadraId);
  const dias = DIAS_SEMANA.filter((d) => contrato.diasSemana.includes(d.valor))
    .map((d) => d.curto)
    .join(", ");

  return (
    <article
      id={`contrato-${contrato.id}`}
      className={`bg-slate-900 border rounded-2xl p-5 space-y-4 ${
        contrato.ativo ? "border-slate-700/50" : "border-slate-800 opacity-70"
      }`}
    >
      <header className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <h3 className="text-base font-bold text-white">{contrato.nome}</h3>
          <p className="text-xs text-slate-500 mt-0.5">
            {contrato.esporte ?? "Esporte não informado"} ·{" "}
            {contrato.tipo === "escolinha" ? "Escolinha" : "Grupo comum"}
          </p>
        </div>
        <span
          className={`text-[11px] font-semibold px-2.5 py-1 rounded-full border ${
            contrato.ativo
              ? "bg-emerald-500/10 text-emerald-400 border-emerald-500/30"
              : "bg-slate-800 text-slate-500 border-slate-700"
          }`}
        >
          {contrato.ativo ? `${sessoesFuturas} sessões futuras` : "Encerrado"}
        </span>
      </header>

      <dl className="grid sm:grid-cols-2 gap-x-6 gap-y-2 text-xs text-slate-400">
        <div className="flex items-center gap-2">
          <CalendarDays className="w-3.5 h-3.5 text-slate-500 flex-shrink-0" />
          <dd>
            {dias} · {contrato.meses} {contrato.meses === 1 ? "mês" : "meses"} desde{" "}
            {formatarDataExibicao(contrato.dataInicio, { day: "numeric", month: "short", year: "numeric" })}
          </dd>
        </div>
        <div className="flex items-center gap-2">
          <Clock className="w-3.5 h-3.5 text-slate-500 flex-shrink-0" />
          <dd>
            {contrato.horaInicio} – {contrato.horaFim}
          </dd>
        </div>
        <div className="flex items-center gap-2">
          <MapPin className="w-3.5 h-3.5 text-slate-500 flex-shrink-0" />
          <dd>{quadra ? `Quadra ${quadra.numero}` : contrato.quadraId}</dd>
        </div>
        <div className="flex items-center gap-2">
          <User className="w-3.5 h-3.5 text-slate-500 flex-shrink-0" />
          <dd>{contrato.responsavelNome}</dd>
        </div>
        <div className="flex items-center gap-2">
          <Phone className="w-3.5 h-3.5 text-slate-500 flex-shrink-0" />
          <dd>{mascaraWhatsApp(contrato.contatoWhatsapp)}</dd>
        </div>
      </dl>

      {children}
    </article>
  );
}

/**
 * Tela do admin: Gestão de Escolinhas.
 * Cadastro de escolinhas com bloqueio recorrente da agenda e divulgação no portal.
 * (Sem regra de cancelamento por sessão — contratos financeiros em backlog.)
 */

"use client";

import { useState } from "react";
import { toast } from "sonner";
import { GraduationCap, Plus } from "lucide-react";
import { useContratosService } from "@/hooks/useContratosService";
import { getHoje } from "@/lib/constants";
import { FormularioContrato } from "./recorrencia/FormularioContrato";
import { CartaoContrato } from "./recorrencia/CartaoContrato";

export function AdminEscolinhasPage() {
  const { getContratosPorTipo, getOcorrencias, criarContrato, encerrarContrato } =
    useContratosService();
  const [mostrarForm, setMostrarForm] = useState(false);

  const escolinhas = getContratosPorTipo("escolinha");
  const hoje = getHoje();

  async function handleEncerrar(id: string, nome: string) {
    const confirmado = window.confirm(
      `Encerrar o contrato de "${nome}"? As sessões de hoje em diante serão liberadas na agenda.`
    );
    if (!confirmado) return;

    const resultado = await encerrarContrato(id);
    if (resultado.ok) {
      toast.success("Contrato encerrado", {
        description: `${resultado.sessoesCanceladas} sessões foram liberadas na agenda.`,
      });
    } else {
      toast.error("Não foi possível encerrar o contrato.");
    }
  }

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center gap-2">
            <GraduationCap className="w-6 h-6 text-violet-400" />
            Escolinhas
          </h1>
          <p className="text-slate-400 text-sm mt-1">
            Horários exclusivos bloqueados na agenda e divulgados no portal com contato para matrícula.
          </p>
        </div>
        {!mostrarForm && (
          <button
            id="escolinhas-nova"
            onClick={() => setMostrarForm(true)}
            className="flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl text-sm font-bold text-slate-950 bg-emerald-500 hover:bg-emerald-400 transition-colors"
          >
            <Plus className="w-4 h-4" />
            Nova escolinha
          </button>
        )}
      </div>

      {mostrarForm && (
        <FormularioContrato
          tipo="escolinha"
          onSubmit={criarContrato}
          onCancelar={() => setMostrarForm(false)}
          onSucesso={(resultado) => {
            setMostrarForm(false);
            toast.success("Escolinha cadastrada", {
              description: `${resultado.totalOcorrencias} sessões bloqueadas na agenda.`,
            });
          }}
        />
      )}

      {escolinhas.length === 0 && !mostrarForm && (
        <div className="bg-slate-900 border border-slate-700/50 rounded-2xl p-10 text-center">
          <GraduationCap className="w-10 h-10 text-slate-600 mx-auto mb-3" />
          <p className="text-slate-400 font-medium">Nenhuma escolinha cadastrada</p>
          <p className="text-slate-600 text-sm mt-1">
            Cadastre uma escolinha para bloquear seus horários e divulgá-la no portal.
          </p>
        </div>
      )}

      <div className="space-y-4">
        {escolinhas.map((contrato) => {
          const sessoesFuturas = getOcorrencias(contrato.id).filter(
            (o) => o.data >= hoje && o.status !== "cancelada"
          ).length;

          return (
            <CartaoContrato key={contrato.id} contrato={contrato} sessoesFuturas={sessoesFuturas}>
              {contrato.descricao && (
                <p className="text-xs text-slate-500 border-t border-slate-800 pt-3">
                  {contrato.descricao}
                </p>
              )}
              {contrato.ativo && (
                <div className="flex justify-end border-t border-slate-800 pt-3">
                  <button
                    id={`encerrar-${contrato.id}`}
                    onClick={() => handleEncerrar(contrato.id, contrato.nome)}
                    className="text-xs font-medium text-red-400 hover:text-red-300 px-3 py-1.5 rounded-lg hover:bg-red-500/10 transition-colors"
                  >
                    Encerrar contrato
                  </button>
                </div>
              )}
            </CartaoContrato>
          );
        })}
      </div>
    </div>
  );
}

/**
 * Lista as sessões de um grupo comum e permite registrar o aviso de cancelamento
 * (com a data do aviso) ou reativar uma sessão cancelada.
 */

"use client";

import { useState } from "react";
import { toast } from "sonner";
import type { Reserva } from "@/store/useReservasStore";
import { formatarDataExibicao, formatarMoeda, getHoje } from "@/lib/constants";
import {
  ANTECEDENCIA_MINIMA_DIAS,
  ROTULO_SITUACAO_COBRANCA,
  type SituacaoCobranca,
} from "@/lib/recorrencia/cancelamento";
import type { useContratosService } from "@/hooks/useContratosService";

type Servico = ReturnType<typeof useContratosService>;

interface Props {
  ocorrencias: Reserva[];
  getSituacaoCobranca: Servico["getSituacaoCobranca"];
  registrarCancelamentoGrupo: Servico["registrarCancelamentoGrupo"];
  reativarOcorrenciaGrupo: Servico["reativarOcorrenciaGrupo"];
}

const ESTILO_SITUACAO: Record<SituacaoCobranca, string> = {
  sem_onus: "bg-slate-700/40 text-slate-300 border-slate-600/50",
  aguardando_reposicao: "bg-amber-500/10 text-amber-300 border-amber-500/30",
  isento_por_reposicao: "bg-emerald-500/10 text-emerald-300 border-emerald-500/30",
  cobranca_devida: "bg-red-500/10 text-red-300 border-red-500/30",
};

export function PainelOcorrenciasGrupo({
  ocorrencias,
  getSituacaoCobranca,
  registrarCancelamentoGrupo,
  reativarOcorrenciaGrupo,
}: Props) {
  const hoje = getHoje();
  const [mostrarPassadas, setMostrarPassadas] = useState(false);
  const [emCancelamento, setEmCancelamento] = useState<string | null>(null);
  const [dataAviso, setDataAviso] = useState(hoje);

  const visiveis = ocorrencias.filter(
    (o) => mostrarPassadas || o.data >= hoje || (o.status === "cancelada" && !!o.avisoCancelamentoEm)
  );

  function abrirCancelamento(id: string) {
    setEmCancelamento(id);
    setDataAviso(hoje);
  }

  function confirmarCancelamento(id: string) {
    const resultado = registrarCancelamentoGrupo(id, dataAviso);
    if (!resultado.ok) {
      toast.error("Não foi possível cancelar", { description: resultado.motivo });
      return;
    }
    setEmCancelamento(null);

    if (resultado.classificacao === "sem_onus") {
      toast.success("Sessão cancelada sem ônus", {
        description: "Aviso com antecedência suficiente. O horário foi liberado ao público.",
      });
    } else {
      toast.warning("Aviso tardio registrado", {
        description:
          "Horário liberado ao público. O grupo só fica isento se outro cliente reservar e pagar.",
        duration: 7000,
      });
    }
  }

  function reativar(id: string) {
    const resultado = reativarOcorrenciaGrupo(id);
    if (resultado.ok) {
      toast.success("Sessão reativada");
    } else {
      toast.error("Não foi possível reativar", { description: resultado.motivo });
    }
  }

  return (
    <div className="border-t border-slate-800 pt-4 space-y-3">
      <div className="flex items-center justify-between">
        <p className="text-xs font-semibold uppercase tracking-wider text-slate-500">Sessões</p>
        <button
          onClick={() => setMostrarPassadas((v) => !v)}
          className="text-xs text-slate-400 hover:text-white transition-colors"
        >
          {mostrarPassadas ? "Ocultar passadas" : "Mostrar passadas"}
        </button>
      </div>

      <p className="text-[11px] text-slate-600">
        Cancelamento sem ônus exige aviso com {ANTECEDENCIA_MINIMA_DIAS} dias ou mais de antecedência.
      </p>

      {visiveis.length === 0 && (
        <p className="text-sm text-slate-500 py-3 text-center">Nenhuma sessão para exibir.</p>
      )}

      <ul className="divide-y divide-slate-800 max-h-80 overflow-y-auto pr-1">
        {visiveis.map((o) => {
          const cancelada = o.status === "cancelada";
          const futura = o.data >= hoje;
          const situacao = cancelada ? getSituacaoCobranca(o) : null;

          return (
            <li key={o.id} className="py-2.5 space-y-2">
              <div className="flex flex-wrap items-center justify-between gap-2">
                <div className="min-w-0">
                  <p className={`text-sm font-medium ${cancelada ? "text-slate-500 line-through" : "text-white"}`}>
                    {formatarDataExibicao(o.data, { weekday: "short", day: "numeric", month: "short" })}
                  </p>
                  {situacao && o.avisoCancelamentoEm && (
                    <p className="text-[11px] text-slate-500">
                      Aviso em {formatarDataExibicao(o.avisoCancelamentoEm, { day: "numeric", month: "short" })}
                    </p>
                  )}
                </div>

                <div className="flex items-center gap-2">
                  {situacao && (
                    <span
                      className={`text-[11px] font-semibold px-2.5 py-1 rounded-full border ${ESTILO_SITUACAO[situacao]}`}
                    >
                      {ROTULO_SITUACAO_COBRANCA[situacao]}
                      {situacao === "cobranca_devida" && ` · ${formatarMoeda(o.valorTotal)}`}
                    </span>
                  )}

                  {!cancelada && futura && emCancelamento !== o.id && (
                    <button
                      id={`cancelar-sessao-${o.id}`}
                      onClick={() => abrirCancelamento(o.id)}
                      className="text-xs font-medium text-red-400 hover:text-red-300 px-2.5 py-1 rounded-lg hover:bg-red-500/10 transition-colors"
                    >
                      Registrar cancelamento
                    </button>
                  )}

                  {cancelada && futura && o.avisoCancelamentoEm && (
                    <button
                      onClick={() => reativar(o.id)}
                      className="text-xs font-medium text-emerald-400 hover:text-emerald-300 px-2.5 py-1 rounded-lg hover:bg-emerald-500/10 transition-colors"
                    >
                      Reativar
                    </button>
                  )}
                </div>
              </div>

              {emCancelamento === o.id && (
                <div className="flex flex-wrap items-end gap-3 bg-slate-800/60 border border-slate-700/50 rounded-xl p-3">
                  <div>
                    <label htmlFor={`aviso-${o.id}`} className="block text-[11px] text-slate-400 mb-1">
                      Data em que o grupo avisou
                    </label>
                    <input
                      id={`aviso-${o.id}`}
                      type="date"
                      max={hoje}
                      value={dataAviso}
                      onChange={(e) => setDataAviso(e.target.value)}
                      className="bg-slate-900 border border-slate-700 rounded-lg px-2.5 py-1.5 text-xs text-white"
                    />
                  </div>
                  <button
                    onClick={() => confirmarCancelamento(o.id)}
                    className="px-3 py-2 rounded-lg text-xs font-bold bg-red-500 text-white hover:bg-red-400 transition-colors"
                  >
                    Confirmar
                  </button>
                  <button
                    onClick={() => setEmCancelamento(null)}
                    className="px-3 py-2 rounded-lg text-xs text-slate-400 hover:text-white transition-colors"
                  >
                    Voltar
                  </button>
                </div>
              )}
            </li>
          );
        })}
      </ul>
    </div>
  );
}

/**
 * Tela do admin: Gestão de Grupos Comuns (mensalistas).
 * Cadastro de grupos com horário cativo e controle de cancelamentos
 * (aviso de 1 semana, reposição e cobrança).
 */

"use client";

import { useState } from "react";
import { toast } from "sonner";
import { Plus, Users } from "lucide-react";
import { useContratosService } from "@/hooks/useContratosService";
import { formatarMoeda, getHoje } from "@/lib/constants";
import { FormularioContrato } from "./recorrencia/FormularioContrato";
import { CartaoContrato } from "./recorrencia/CartaoContrato";
import { PainelOcorrenciasGrupo } from "./recorrencia/PainelOcorrenciasGrupo";

export function AdminGruposPage() {
  const {
    getContratosPorTipo,
    getOcorrencias,
    getSituacaoCobranca,
    criarContrato,
    registrarCancelamentoGrupo,
    reativarOcorrenciaGrupo,
    encerrarContrato,
  } = useContratosService();
  const [mostrarForm, setMostrarForm] = useState(false);
  const [expandidos, setExpandidos] = useState<Set<string>>(new Set());

  const grupos = getContratosPorTipo("grupo");
  const hoje = getHoje();

  function alternarExpandido(id: string) {
    setExpandidos((atual) => {
      const proximo = new Set(atual);
      if (proximo.has(id)) proximo.delete(id);
      else proximo.add(id);
      return proximo;
    });
  }

  async function handleEncerrar(id: string, nome: string) {
    const confirmado = window.confirm(
      `Encerrar o contrato do grupo "${nome}"? As sessões de hoje em diante serão liberadas sem cobrança.`
    );
    if (!confirmado) return;

    const resultado = await encerrarContrato(id);
    if (resultado.ok) {
      toast.success("Contrato encerrado", {
        description: `${resultado.sessoesCanceladas} sessões foram liberadas na agenda.`,
      });
    } else {
      toast.error("Não foi possível encerrar o contrato.");
    }
  }

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center gap-2">
            <Users className="w-6 h-6 text-sky-400" />
            Grupos
          </h1>
          <p className="text-slate-400 text-sm mt-1">
            Horários cativos para grupos de amigos, sem pagamento adiantado. Cancelamentos com menos de 1
            semana só são abonados se o horário for reposto.
          </p>
        </div>
        {!mostrarForm && (
          <button
            id="grupos-novo"
            onClick={() => setMostrarForm(true)}
            className="flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl text-sm font-bold text-slate-950 bg-emerald-500 hover:bg-emerald-400 transition-colors"
          >
            <Plus className="w-4 h-4" />
            Novo grupo
          </button>
        )}
      </div>

      {mostrarForm && (
        <FormularioContrato
          tipo="grupo"
          onSubmit={criarContrato}
          onCancelar={() => setMostrarForm(false)}
          onSucesso={(resultado) => {
            setMostrarForm(false);
            toast.success("Grupo cadastrado", {
              description: `${resultado.totalOcorrencias} sessões bloqueadas na agenda.`,
            });
          }}
        />
      )}

      {grupos.length === 0 && !mostrarForm && (
        <div className="bg-slate-900 border border-slate-700/50 rounded-2xl p-10 text-center">
          <Users className="w-10 h-10 text-slate-600 mx-auto mb-3" />
          <p className="text-slate-400 font-medium">Nenhum grupo cadastrado</p>
          <p className="text-slate-600 text-sm mt-1">
            Cadastre um grupo para reservar um horário fixo com prioridade.
          </p>
        </div>
      )}

      <div className="space-y-4">
        {grupos.map((contrato) => {
          const ocorrencias = getOcorrencias(contrato.id);
          const sessoesFuturas = ocorrencias.filter(
            (o) => o.data >= hoje && o.status !== "cancelada"
          ).length;

          const cobrancas = ocorrencias.filter(
            (o) => o.status === "cancelada" && getSituacaoCobranca(o) === "cobranca_devida"
          );
          const totalDevido = cobrancas.reduce((soma, o) => soma + o.valorTotal, 0);
          const aberto = expandidos.has(contrato.id);

          return (
            <CartaoContrato key={contrato.id} contrato={contrato} sessoesFuturas={sessoesFuturas}>
              {cobrancas.length > 0 && (
                <p className="text-xs text-red-300 bg-red-500/10 border border-red-500/30 rounded-xl px-3.5 py-2.5">
                  {cobrancas.length} sessão(ões) cancelada(s) fora do prazo sem reposição ·{" "}
                  <strong>{formatarMoeda(totalDevido)}</strong> a cobrar
                </p>
              )}

              <div className="flex flex-wrap items-center justify-between gap-2 border-t border-slate-800 pt-3">
                <button
                  id={`sessoes-${contrato.id}`}
                  onClick={() => alternarExpandido(contrato.id)}
                  className="text-xs font-medium text-emerald-400 hover:text-emerald-300 px-3 py-1.5 rounded-lg hover:bg-emerald-500/10 transition-colors"
                >
                  {aberto ? "Ocultar sessões" : "Gerenciar sessões e cancelamentos"}
                </button>
                {contrato.ativo && (
                  <button
                    id={`encerrar-${contrato.id}`}
                    onClick={() => handleEncerrar(contrato.id, contrato.nome)}
                    className="text-xs font-medium text-red-400 hover:text-red-300 px-3 py-1.5 rounded-lg hover:bg-red-500/10 transition-colors"
                  >
                    Encerrar contrato
                  </button>
                )}
              </div>

              {aberto && (
                <PainelOcorrenciasGrupo
                  ocorrencias={ocorrencias}
                  getSituacaoCobranca={getSituacaoCobranca}
                  registrarCancelamentoGrupo={registrarCancelamentoGrupo}
                  reativarOcorrenciaGrupo={reativarOcorrenciaGrupo}
                />
              )}
            </CartaoContrato>
          );
        })}
      </div>
    </div>
  );
}

