/**
 * Banner promocional exibido na agenda do portal quando um horário
 * pertence a uma escolinha. Abre o modal "saiba mais" ao clicar.
 */

"use client";

import { useState } from "react";
import { GraduationCap, ChevronRight } from "lucide-react";
import type { AvisoEscolinha } from "@/lib/recorrencia/agenda";
import { ModalEscolinha } from "./ModalEscolinha";

interface Props {
  avisos: AvisoEscolinha[];
}

export function BannerEscolinha({ avisos }: Props) {
  const [selecionado, setSelecionado] = useState<AvisoEscolinha | null>(null);

  if (avisos.length === 0) return null;

  return (
    <>
      <div className="space-y-2 mb-4">
        {avisos.map((aviso) => (
          <button
            key={`${aviso.contratoId}-${aviso.horaInicio}`}
            type="button"
            id={`banner-escolinha-${aviso.contratoId}`}
            onClick={() => setSelecionado(aviso)}
            className="w-full text-left flex items-center gap-3 rounded-xl border border-violet-500/30 bg-violet-500/10 hover:bg-violet-500/15 px-3.5 py-3 transition-colors"
          >
            <span className="w-8 h-8 rounded-lg bg-violet-500/20 flex items-center justify-center flex-shrink-0">
              <GraduationCap className="w-4 h-4 text-violet-300" />
            </span>
            <span className="flex-1 text-xs text-violet-100 leading-relaxed">
              Este é o horário da escolinha <strong>{aviso.nome}</strong>
              {aviso.esporte ? ` de ${aviso.esporte}` : ""}, das{" "}
              <strong>
                {aviso.horaInicio} às {aviso.horaFim}
              </strong>
              . <span className="underline underline-offset-2">Clique aqui para saber mais.</span>
            </span>
            <ChevronRight className="w-4 h-4 text-violet-400 flex-shrink-0" />
          </button>
        ))}
      </div>

      <ModalEscolinha aviso={selecionado} onClose={() => setSelecionado(null)} />
    </>
  );
}

/**
 * Modal "saiba mais" da escolinha: informações e botão de matrícula via WhatsApp.
 */

"use client";

import { MessageCircle, Clock, CalendarDays, User } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { mascaraWhatsApp } from "@/lib/constants";
import { montarLinkWhatsApp, type AvisoEscolinha } from "@/lib/recorrencia/agenda";
import { DIAS_SEMANA } from "@/lib/recorrencia/types";

interface Props {
  aviso: AvisoEscolinha | null;
  onClose: () => void;
}

export function ModalEscolinha({ aviso, onClose }: Props) {
  const dias = aviso?.diasSemana
    ? DIAS_SEMANA.filter((d) => aviso.diasSemana?.includes(d.valor))
        .map((d) => d.longo)
        .join(", ")
    : null;

  const mensagem = aviso
    ? `Olá! Vi a escolinha ${aviso.nome}${aviso.esporte ? ` de ${aviso.esporte}` : ""} no Reservei e gostaria de informações sobre a matrícula.`
    : "";

  return (
    <Dialog open={aviso !== null} onOpenChange={(aberto) => !aberto && onClose()}>
      <DialogContent className="bg-slate-900 border border-slate-700 text-white sm:max-w-md">
        {aviso && (
          <>
            <DialogHeader>
              <DialogTitle className="text-lg font-bold text-white">{aviso.nome}</DialogTitle>
              <DialogDescription className="text-slate-400">
                Escolinha{aviso.esporte ? ` de ${aviso.esporte}` : ""} que utiliza este horário.
              </DialogDescription>
            </DialogHeader>

            <div className="space-y-3 text-sm text-slate-300">
              <p className="flex items-center gap-2">
                <Clock className="w-4 h-4 text-violet-400" />
                {aviso.horaInicio} às {aviso.horaFim}
              </p>
              {dias && (
