// ─── Tipos e Helpers de Agrupamento ──────────────────────────────────────────

type SlotItem =
  | { tipo: "regular"; horario: string }
  | { tipo: "escolinha"; aviso: AvisoEscolinha; horarios: string[] };

function agruparSlots(
  horarios: string[],
  horariosOcupados: string[],
  avisosEscolinha: AvisoEscolinha[]
): SlotItem[] {
  const itens: SlotItem[] = [];

  for (const horario of horarios) {
    const isOcupado = horariosOcupados.includes(horario);
    const aviso = avisosEscolinha.find((a) => a.horarios.includes(horario));
    const isEscolinha = isOcupado && !!aviso;

    if (isEscolinha && aviso) {
      const ultimo = itens[itens.length - 1];
      if (ultimo && ultimo.tipo === "escolinha" && ultimo.aviso.contratoId === aviso.contratoId) {
        ultimo.horarios.push(horario);
      } else {
        itens.push({ tipo: "escolinha", aviso, horarios: [horario] });
      }
    } else {
      itens.push({ tipo: "regular", horario });
    }
  }

  return itens;
}

// ─── Componente ───────────────────────────────────────────────────────────────

export function HorarioGrid({
  dataSelecionada,
  horariosSelecionados,
  horariosOcupados,
  avisosEscolinha = [],
  onToggleHorario,
}: Props) {
  const [isMounted, setIsMounted] = useState(false);
  const [avisoSelecionado, setAvisoSelecionado] = useState<AvisoEscolinha | null>(null);

  useEffect(() => {
    setIsMounted(true);
  }, []);

  const handleClick = (horario: string) => {
    if (horariosOcupados.includes(horario)) return;
    if (isHorarioExpirado(dataSelecionada, horario, 10)) return;

    const isSelecionado = horariosSelecionados.includes(horario);
    if (!isSelecionado) {
      const proximo = [...horariosSelecionados, horario];
      if (!saoConsecutivos(proximo)) {
        toast.error("Selecione horários consecutivos", {
          description: "Ex: 13h → 14h → 15h. Não é possível pular horários.",
        });
        return;
      }
    }
    onToggleHorario(horario);
  };

  // Agrupar slots por faixa
  const grupos: Array<{ faixa: string; horarios: string[] }> = [];
  let faixaAtual = "";
  for (const h of HORARIOS_DISPONIVEIS) {
    const f = getFaixa(parseInt(h.split(":")[0], 10));
    if (f !== faixaAtual) {
      faixaAtual = f;
      grupos.push({ faixa: f, horarios: [] });
    }
    grupos[grupos.length - 1].horarios.push(h);
  }

  return (
    <div className="space-y-3.5">
      {grupos.map(({ faixa, horarios }) => {
        const itensAgrupados = agruparSlots(horarios, horariosOcupados, avisosEscolinha);

        return (
          <div key={faixa}>
            {/* ── Label da faixa ── */}
            <div className="flex flex-wrap items-baseline gap-x-3 gap-y-1 mb-2">
              <span className={cn("text-xs font-bold uppercase tracking-wider", FAIXA[faixa].cor)}>
                {FAIXA[faixa].label}
              </span>
              <span className="text-base sm:text-lg font-black text-white">
                {PRECO_POR_FAIXA[faixa]}
              </span>
              <span className="text-xs text-slate-500 font-medium">
                ({FAIXA[faixa].faixaHora})
              </span>
            </div>

            {/* ── Chips de horário com agrupamento de escolinha ── */}
            <div className="flex flex-wrap items-center gap-2">
              {itensAgrupados.map((item, idx) => {
                if (item.tipo === "regular") {
                  const horario = item.horario;
                  const hora = parseInt(horario.split(":")[0], 10);
                  const horaFim = String(hora + 1).padStart(2, "0") + ":00";
                  const isSelecionado = horariosSelecionados.includes(horario);
                  const isOcupado = horariosOcupados.includes(horario);
                  const expiradoParaSelecao = isMounted
                    ? isHorarioExpirado(dataSelecionada, horario, 10)
                    : false;
                  const isDisabled = isOcupado || expiradoParaSelecao;

                  return (
                    <button
                      key={horario}
                      onClick={() => handleClick(horario)}
                      disabled={isDisabled}
                      title={
                        isOcupado
                          ? "Horário ocupado"
                          : expiradoParaSelecao
                          ? "Horário indisponível"
                          : `${horario} – ${horaFim}`
                      }
                      className={cn(
                        "inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl border text-xs font-semibold transition-all duration-150 select-none h-8",
                        isSelecionado
                          ? "bg-emerald-500/25 border-emerald-500 text-emerald-300 shadow-sm"
                          : isDisabled
                          ? "bg-slate-900/40 border-slate-800 text-slate-700 cursor-not-allowed line-through"
                          : "bg-slate-800/50 border-slate-700 text-slate-300 hover:bg-slate-700 hover:border-slate-600 active:scale-95"
                      )}
                    >
                      <span className="whitespace-nowrap">
                        {isSelecionado && "✓ "}
                        {horario} – {horaFim}
                      </span>
                    </button>
                  );
                }

                // ── Bloco de Escolinha: divider + tag inline + botões + divider ──
                const { aviso, horarios: slotsEscolinha } = item;
                return (
                  <div
                    key={`bloco-escolinha-${aviso.contratoId}-${idx}`}
                    className="inline-flex items-center gap-2"
                  >
                    {/* Divider sutil cinza esquerdo (perfeitamente centralizado) */}
                    <div className="w-[1.5px] h-5 bg-slate-700 rounded-full self-center mx-0.5" />

                    {/* Tag da escolinha fora dos cards (inline no mesmo nível) */}
                    <button
                      type="button"
                      onClick={() => setAvisoSelecionado(aviso)}
                      title={`Escolinha: ${aviso.nome} - Clique para ver informações`}
                      className="inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-xl border border-violet-500/40 bg-violet-950/60 hover:bg-violet-900/70 text-violet-300 text-xs font-semibold transition-all cursor-pointer shadow-xs h-8 select-none"
                    >
                      <GraduationCap className="w-3.5 h-3.5 text-violet-400 flex-shrink-0" />
                      <span className="max-w-[130px] truncate">{aviso.nome}</span>
                    </button>

                    {/* Cards dos horários da escolinha (apenas horário, sem tag interna) */}
                    {slotsEscolinha.map((horario) => {
                      const hora = parseInt(horario.split(":")[0], 10);
                      const horaFim = String(hora + 1).padStart(2, "0") + ":00";

                      return (
                        <button
                          key={horario}
                          onClick={() => setAvisoSelecionado(aviso)}
                          title={`Horário de escolinha: ${aviso.nome} - Clique para ver detalhes`}
                          className="inline-flex items-center px-3 py-1.5 rounded-xl border text-xs font-semibold bg-violet-500/15 border-violet-500/40 text-violet-200 hover:bg-violet-500/25 cursor-pointer ring-1 ring-violet-500/20 transition-all duration-150 select-none h-8 whitespace-nowrap"
                        >
                          {horario} – {horaFim}
                        </button>
                      );
                    })}

                    {/* Divider sutil cinza direito (perfeitamente centralizado) */}
                    <div className="w-[1.5px] h-5 bg-slate-700 rounded-full self-center mx-0.5" />
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}

      <ModalEscolinha aviso={avisoSelecionado} onClose={() => setAvisoSelecionado(null)} />
    </div>
  );
}

