    getOcorrencias,
    getAvisosEscolinha,
    getSituacaoCobranca,
    criarContrato,
    atualizarContrato,
    registrarCancelamentoGrupo,
    reativarOcorrenciaGrupo,
    encerrarContrato,
  ]
);

